import { createHmac, timingSafeEqual } from 'node:crypto';
import { ApplicationError } from 'n8n-workflow';
import type { IDataObject } from 'n8n-workflow';
import { encodePath } from '../../shared/transport';
import type { RequestSpec } from '../../shared/types';

/**
 * One Dutify service the trigger can subscribe to. `cfg` carries the selected `workspace` and the
 * source's own settings (for PM: `eventTypes`, `scopeType`, `scopeEntityIdentifier`).
 */
export interface WebhookSource {
	/** Registers `url`. `secret` is generated by the trigger and signs every delivery. */
	create(url: string, secret: string, cfg: IDataObject): RequestSpec;
	/** The id of the created webhook. The secret is the generated one: Dutify never returns it. */
	parseCreated(res: unknown, secret: string): { id: string; secret: string };
	list(cfg: IDataObject): RequestSpec;
	/** The id of a listed webhook delivering to `url` (and, when given, with that `id`), else null. */
	findExisting(res: unknown, url: string, id?: string): string | null;
	remove(id: string, cfg: IDataObject): RequestSpec;
	/** Stops deliveries without deleting; used when the service refuses the delete. */
	deactivate(id: string, cfg: IDataObject): RequestSpec;
	/** Lowercase, as n8n hands over request headers. */
	signatureHeader: string;
}

interface PmWebhookRow {
	identifier?: string;
	url?: string;
}

const pmWebhooksPath = (cfg: IDataObject) =>
	encodePath`/mp/api/v1/workspaces/${String(cfg.workspace ?? '')}/webhooks`;

/** PM webhook subscriptions (Webhook Resource). Deliveries carry `X-Webhook-Signature-256`. */
const pm: WebhookSource = {
	create(url, secret, cfg) {
		const body: IDataObject = { url, secret, name: 'n8n', eventTypes: cfg.eventTypes };
		if (cfg.scopeType) {
			body.scopeType = cfg.scopeType;
			body.scopeEntityIdentifier = cfg.scopeEntityIdentifier;
		}

		return { method: 'POST', path: pmWebhooksPath(cfg), body };
	},
	parseCreated(res, secret) {
		const id = (res as PmWebhookRow | null)?.identifier;
		if (!id) {
			throw new ApplicationError('Dutify did not return the ID of the created webhook');
		}

		return { id, secret };
	},
	list(cfg) {
		return { method: 'GET', path: pmWebhooksPath(cfg) };
	},
	findExisting(res, url, id) {
		const rows = Array.isArray(res) ? (res as PmWebhookRow[]) : [];
		const found = rows.find(
			(row) => row.identifier && row.url === url && (id === undefined || row.identifier === id),
		);

		return found?.identifier ?? null;
	},
	remove(id, cfg) {
		return { method: 'DELETE', path: `${pmWebhooksPath(cfg)}/${encodeURIComponent(id)}` };
	},
	deactivate(id, cfg) {
		// UpdateWebhookRequest: every field is optional, so this only switches the webhook off.
		return {
			method: 'PUT',
			path: `${pmWebhooksPath(cfg)}/${encodeURIComponent(id)}`,
			body: { active: false },
		};
	},
	signatureHeader: 'x-webhook-signature-256',
};

/**
 * Sources by the value of the trigger's `source` property. Only PM for now: Hub API keys are
 * refused on `/webhooks`, so there is no `meeting` source. Later: `codexum` (wiki), `roadmarq`
 * (feature requests), `meeting` (Hub, once its keys may manage webhooks).
 */
export const sources: Record<string, WebhookSource> = { pm };

const SIGNATURE_PREFIX = 'sha256=';

/**
 * Whether `header` is `sha256=` + the lowercase hex HMAC-SHA256 of the raw body keyed by `secret`.
 * The comparison is timing-safe.
 */
export function verifySignature(
	secret: string,
	rawBody: Buffer | undefined,
	header: string | undefined,
): boolean {
	if (!secret || !rawBody || typeof header !== 'string' || !header.startsWith(SIGNATURE_PREFIX)) {
		return false;
	}
	const expected = Buffer.from(
		SIGNATURE_PREFIX + createHmac('sha256', secret).update(rawBody).digest('hex'),
	);
	const actual = Buffer.from(header);

	return actual.length === expected.length && timingSafeEqual(actual, expected);
}
